    @Test
    void recover_idempotentReplayAndConflictAndFailureNotOccupyingKey() throws Exception {
        registerLeg("LEG1", "PEK", "SHA");
        registerBag("BAG1", List.of("LEG1"));
        load("LEG1", 1, List.of("BAG1"));
        seal("LEG1", 2);
